exercises.reference_solution:
def log_entry(message, level="NOTICE", source="field"):
    return f"[{level}][{source}] {message}"

dispatch_log = [
    log_entry("gate checked"),
    log_entry("venom found", "ALERT"),
    log_entry("signal clear", source="tower"),
]

for line in dispatch_log:
    print(line)
